capture_editorial_notification.definition:
CREATE OR REPLACE FUNCTION public.capture_editorial_notification()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
declare changed boolean; hours integer;
begin
  changed := TG_OP='INSERT';
  if TG_OP='UPDATE' then
    changed := new.assigned_to is distinct from old.assigned_to
      or new.review_due_at is distinct from old.review_due_at
      or (new.status in ('draft','pending_review')) <> (old.status in ('draft','pending_review'));
  end if;
  if changed then
    new.notification_epoch := coalesce(new.notification_epoch,0)+1;
    if new.assigned_to is not null and new.status in ('draft','pending_review') then
      new.review_assigned_at := statement_timestamp();
      if new.review_due_at is null then
        select deadline_hours into hours from public.editorial_notification_policy;
        new.review_due_at := statement_timestamp() + make_interval(hours=>hours);
      end if;
    end if;
  end if;
  return new;
end $function$

protect_editorial_job_input.definition:
CREATE OR REPLACE FUNCTION public.protect_editorial_job_input()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$ begin
  if TG_OP='DELETE' then raise exception 'Editorial generation evidence cannot be deleted'; end if;
  if (to_jsonb(new)-array['status','attempts','claim_token','claimed_at','available_at','result_revision_id','failure_code','updated_at'])
     is distinct from
     (to_jsonb(old)-array['status','attempts','claim_token','claimed_at','available_at','result_revision_id','failure_code','updated_at'])
     or (old.result_revision_id is not null and new.result_revision_id is distinct from old.result_revision_id) then
    raise exception 'Editorial generation inputs and results are immutable';
  end if;
  return new;
end $function$

protect_generated_revision_body.definition:
CREATE OR REPLACE FUNCTION public.protect_generated_revision_body()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$ begin
  if (new.body,new.base_version,new.concept_id) is distinct from (old.body,old.base_version,old.concept_id)
    and exists(select 1 from public.editorial_generation_jobs
      where source_revision_id=old.id or result_revision_id=old.id) then
    raise exception 'Generated revision evidence is immutable; stage a new revision';
  end if;
  return new;
end $function$

touch_updated_at.definition:
CREATE OR REPLACE FUNCTION public.touch_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  new.updated_at = now();
  return new;
end;
$function$
